package com.foodie.order;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;@Entity @Table(name="customer_order") class CustomerOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long orderId;@Column(nullable=false) Long customerId;@Column(nullable=false) Long restaurantId;@Column(nullable=false) LocalDateTime orderDate;@Column(nullable=false,precision=10,scale=2) BigDecimal totalAmount;@Enumerated(EnumType.STRING) @Column(nullable=false,length=30) OrderStatus status;@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) List<OrderItem> items=new ArrayList<>();void add(OrderItem i){items.add(i);i.order=this;}}enum OrderStatus{PLACED,CONFIRMED,PREPARING,OUT_FOR_DELIVERY,DELIVERED,CANCELLED}
